('hi-festive-family-portrait', 'social'::public.library_kind, 'त्योहार फैमिली पोर्ट्रेट (Hindi)', 'दीयों और फूलों के साथ त्योहार वाली फैमिली फोटो।', null, array['gemini','chatgpt']::text[], array[]::text[], array['festival','hindi','family']::text[], 'hi', '4:5', true, 'published'::public.content_status, '2026-10-17'::date),
('bug-fix-with-root-cause', 'developer'::public.library_kind, 'Fix a bug with root-cause analysis', 'Makes the agent find the cause before patching symptoms.', 'Agent patches the symptom (adds a null check) without understanding why it happens.', array['cursor','claude-code','chatgpt','claude']::text[], array[]::text[], array['bug','debugging']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('safe-refactor', 'developer'::public.library_kind, 'Refactor without changing behaviour', 'Behaviour-preserving refactor with tests as a safety net.', 'Refactor silently changes behaviour or touches half the codebase.', array['cursor','claude-code','chatgpt','claude']::text[], array[]::text[], array['refactor']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('write-tests-for-existing-code', 'developer'::public.library_kind, 'Write tests for existing code', 'Covers happy path, edge cases and failures without testing implementation details.', 'Tests only cover the happy path or assert on internals, so they break on every refactor.', array['cursor','claude-code','chatgpt','claude']::text[], array[]::text[], array['tests']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('pr-review', 'developer'::public.library_kind, 'Review a pull request', 'Prioritised review: bugs, security, tests, then style.', 'Review drowns real bugs in nitpicks about naming and formatting.', array['cursor','claude-code','chatgpt','claude']::text[], array[]::text[], array['review','pr']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('explain-codebase', 'developer'::public.library_kind, 'Explain an unfamiliar codebase', 'Map of the code before you start changing it.', 'Agent starts editing a codebase it hasn''t understood.', array['cursor','claude-code','chatgpt','claude']::text[], array[]::text[], array['onboarding','architecture']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('security-audit', 'developer'::public.library_kind, 'Security audit of a feature', 'Targeted OWASP-style review of one feature.', 'Generic security advice instead of findings tied to real code.', array['cursor','claude-code','chatgpt','claude']::text[], array[]::text[], array['security','audit']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('laravel-migration-safe', 'developer'::public.library_kind, 'Laravel: add a safe database migration', 'New column/table with indexes, rollback and model updates.', 'Edits an existing migration, forgets indexes, or breaks rollback.', array['cursor','claude-code','chatgpt','claude']::text[], array['laravel']::text[], array['laravel','migration','database']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('laravel-n-plus-one', 'developer'::public.library_kind, 'Laravel: find and fix N+1 queries', 'Eager loading fixes with proof.', 'Adds with() everywhere blindly, or misses the real N+1 in a Blade/Resource loop.', array['cursor','claude-code','chatgpt','claude']::text[], array['laravel']::text[], array['laravel','performance','eloquent']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('laravel-form-request', 'developer'::public.library_kind, 'Laravel: move validation into a Form Request', 'Thin controllers with proper authorisation.', 'Validation duplicated across controllers and authorize() left returning true.', array['cursor','claude-code','chatgpt','claude']::text[], array['laravel']::text[], array['laravel','validation']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('laravel-queue-job', 'developer'::public.library_kind, 'Laravel: move slow work to a queued job', 'Idempotent jobs with retries and tests.', 'Job is not idempotent, so retries send duplicate emails or charges.', array['cursor','claude-code','chatgpt','claude']::text[], array['laravel']::text[], array['laravel','queue']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('livewire-component', 'developer'::public.library_kind, 'Laravel Livewire: build a component', 'Secure Livewire component with validation and tests.', 'Trusts public properties from the browser and skips authorisation.', array['cursor','claude-code','chatgpt','claude']::text[], array['laravel']::text[], array['laravel','livewire']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('node-endpoint-zod', 'developer'::public.library_kind, 'Node.js: add a validated API endpoint', 'Endpoint with schema validation, errors and tests.', 'Endpoint trusts req.body and returns inconsistent error shapes.', array['cursor','claude-code','chatgpt','claude']::text[], array['node']::text[], array['node','api','validation']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('node-error-handling', 'developer'::public.library_kind, 'Node.js: centralise error handling', 'One error middleware, typed errors, no leaked stack traces.', 'Unhandled promise rejections and stack traces leaking to clients.', array['cursor','claude-code','chatgpt','claude']::text[], array['node']::text[], array['node','errors']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('nextjs-server-component-data', 'developer'::public.library_kind, 'Next.js: fetch data in a Server Component', 'Moves client-side fetching to the server where it belongs.', 'useEffect + fetch on pages that should be server-rendered for speed and SEO.', array['cursor','claude-code','chatgpt','claude']::text[], array['nextjs']::text[], array['nextjs','react','app-router']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('nextjs-route-handler', 'developer'::public.library_kind, 'Next.js: secure route handler / server action', 'Validated, authenticated mutation endpoint.', 'Server action trusts client input and skips auth because ''it''s server code''.', array['cursor','claude-code','chatgpt','claude']::text[], array['nextjs']::text[], array['nextjs','api','security']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('supabase-rls-policy', 'developer'::public.library_kind, 'Supabase: write and test RLS policies', 'Row Level Security that is actually tested.', 'RLS enabled but policies too broad, or service-role key used in the browser.', array['cursor','claude-code','chatgpt','claude']::text[], array['nextjs','node']::text[], array['supabase','postgres','rls','security']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('write-agents-md', 'developer'::public.library_kind, 'Generate AGENTS.md from a repo', 'Have the agent draft its own instructions from real config files.', 'Instruction file full of generic advice that doesn''t match the repo.', array['cursor','claude-code','chatgpt','claude']::text[], array[]::text[], array['agents-md','setup']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('plan-before-code', 'developer'::public.library_kind, 'Plan a feature before coding', 'Implementation plan you approve before any edits.', 'Agent writes 600 lines before you notice it misunderstood the feature.', array['cursor','claude-code','chatgpt','claude']::text[], array[]::text[], array['planning','architecture']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('commit-message', 'developer'::public.library_kind, 'Write a conventional commit message', 'Accurate commit message from the staged diff.', 'Vague messages like ''fix stuff'' or messages describing changes that aren''t in the diff.', array['cursor','claude-code','chatgpt','claude']::text[], array[]::text[], array['git','commit']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('dependency-upgrade', 'developer'::public.library_kind, 'Upgrade a dependency safely', 'Read the changelog, upgrade, fix, verify.', 'Bumps a major version and ''fixes'' errors by disabling checks.', array['cursor','claude-code','chatgpt','claude']::text[], array[]::text[], array['upgrade','dependencies']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('performance-profile', 'developer'::public.library_kind, 'Investigate a slow page or endpoint', 'Measure first, then optimise the real bottleneck.', 'Premature micro-optimisation without measuring.', array['cursor','claude-code','chatgpt','claude']::text[], array[]::text[], array['performance','profiling']::text[], 'en', null, false, 'published'::public.content_status, null::date),
('sql-query-review', 'developer'::public.library_kind, 'Review and optimise a SQL query', 'EXPLAIN-driven query and index review.', 'Adds random indexes without checking the query plan.', array['cursor','claude-code','chatgpt','claude']::text[], array[]::text[], array['sql','database','performance']::text[], 'en', null, false, 'published'::public.content_status, null::date)
on conflict (slug) do update set kind = excluded.kind, title = excluded.title, summary = excluded.summary,
  failure_mode = excluded.failure_mode, targets = excluded.targets, stacks = excluded.stacks, tags = excluded.tags,
  locale = excluded.locale, aspect_ratio = excluded.aspect_ratio, requires_photo = excluded.requires_photo,
  status = excluded.status, last_verified = excluded.last_verified;

insert into public.library_item_bodies (item_id, body)
select li.id, v.body from (values
('instagram-growth-plan', 'You are a social media strategist who has grown Instagram accounts in competitive niches.

My account: [niche / what you post]
Where I am now: [followers, posts per week, what has worked]
Time I can spend: [hours per week]
Goal for the next 30 days: [e.g. more saves and profile visits]

Create a 30-day growth plan:
1. Audience snapshot: who they are, what they want, what makes them stop scrolling.
2. 3–4 content pillars that fit my niche and strengths.
3. 10 specific Reel or carousel ideas, each with a one-line hook.
4. A weekly posting schedule I can realistically keep.
5. Metrics to track (saves, shares, profile visits, follower change) and what to change at the 2-week review.

Rules: don''t promise follower numbers or virality; prefer ideas I can film with a phone.
Format: headings for each part; ideas as a table (idea · format · hook).'),
('reel-script-hook-first', 'Write a 30-second Instagram Reel script about [topic] for [audience].

Structure:
- 0–3s Hook: one line that creates curiosity or names a pain point (give 3 options).
- 3–20s Value: 2–3 quick points or steps, one per shot.
- 20–27s Payoff: the result or key takeaway.
- 27–30s CTA: one simple action (save, comment a keyword, follow for part 2).

For each beat give: what I say, what''s on screen, on-screen text.
Tone: [friendly / energetic / calm]. Keep spoken lines short enough to say naturally.'),
('caption-hook-hashtag-pack', 'Post: [what the post or carousel is about]
Platform: [Instagram / LinkedIn / TikTok]
Audience: [who it''s for]

Give me:
1. 5 hooks, each using a different angle: question, bold claim, mini-story, number/list, contrarian.
2. 2 captions (under 120 words) that expand the hook and end with one clear call to action.
3. 10–15 relevant hashtags split into broad and niche. No banned or irrelevant tags.
Avoid clickbait that the post doesn''t deliver.'),
('youtube-video-plan', 'Plan a YouTube video for my channel about [channel topic].
Video idea: [idea]
Viewer: [who watches and what they want]
Length: [e.g. 8–10 minutes]

Give me:
1. 5 title options (under 60 characters) and a thumbnail concept for each (subject, expression, 2–4 words of text).
2. A hook script for the first 15 seconds that previews the payoff.
3. A timed outline (section · time · key points · B-roll ideas).
4. A natural call to action near the end.
Make sure the video actually delivers what the title promises.'),
('content-calendar-30-days', 'Create a 30-day content calendar.
Business/creator: [what you do]
Platforms: [e.g. Instagram, YouTube Shorts, LinkedIn]
Posting frequency: [e.g. 4 per week]
Key dates this month: [launches, festivals, events]

Use 3–4 content pillars and balance formats (Reels, carousels, stories, text posts).
Output a table: date · platform · format · pillar · topic · hook · repurpose note.
Then list 5 posts that can be batch-created in one session.'),
('linkedin-insight-post', 'Turn this experience into a LinkedIn post:
What happened: [the situation]
What I learned: [the lesson]
Who should read it: [audience]

Rules: open with a specific first line (no "I''m humbled to announce"); short paragraphs; one concrete example; end with a question or a takeaway; max 3 hashtags; don''t exaggerate or invent details.
Give the post (150–250 words) plus 2 alternative opening lines.'),
('validate-business-idea', 'You are a lean startup coach. Help me validate this idea before I build anything.

Idea: [your idea]
Target customer: [who]
Budget for testing: [amount]
Location: [city/market]

1. List the key assumptions (customer, problem, willingness to pay, channel) and rank them by risk.
2. Design one cheap experiment for each of the top 3 (e.g. landing page, pre-orders, concierge test). For each: steps, cost, time, and the pass/fail threshold decided in advance.
3. Write a 10-question customer interview script that avoids leading questions.
Label anything that is your assumption rather than a fact.'),
('competitor-analysis-swot', 'My business: [what you sell, to whom, where]
Competitors I know: [names or links]

1. Suggest other direct and indirect competitors I may have missed (mark ones I should verify).
2. Compare all of them in a table: offer, price range, target customer, channels, strengths, weaknesses.
3. Write a SWOT for my business.
4. Recommend 3 differentiation opportunities I could act on within a month.
Mark any detail you are not sure about as "verify". Don''t invent prices or numbers.'),
('small-business-marketing-plan', 'Create a one-page marketing plan.
Business: [what you sell]
Ideal customer: [who buys and why]
Monthly budget: [amount]
Current channels: [what you already use]

Include: the customer''s buying trigger, a core message with 3 supporting angles, 2–3 channels (explain why they fit the budget), a week-by-week plan for 4 weeks, and 3 metrics to review weekly.
No guaranteed results or made-up benchmarks.'),
('sales-call-script', 'Write a sales call script.
I sell: [offer]
To: [prospect type]
Their likely problem: [problem]

Stages: opening that shows relevance → 3 discovery questions → presenting the offer in their words → handling the 3 most likely objections (table: objection · response) → one clear next step.
Keep it conversational. No pressure tactics or false urgency.'),
('customer-complaint-reply', 'Customer message:
"""
[paste the message]
"""
Our policy: [refund/replacement policy]
What I can offer: [options]

Write a reply that acknowledges the specific problem, apologises without blaming, explains what happens next, offers a solution within policy, and closes warmly. Under 150 words.
Then give a reusable template version with [placeholders].'),
('product-listing-copy', 'Product: [name]
Features/specs (only use these): [list]
Buyer: [who buys it and why]
Marketplace: [Amazon / Shopify / Etsy / Flipkart]

Write: a title with key attributes, 5 benefit-led bullets (each tied to a real feature), a short description, care/size details, and 10 search keywords.
Never invent specifications, certifications or claims.'),
('professional-email-any-situation', 'You are a senior communications coach who writes clear, warm emails that get a yes on the first read.

To: [recipient and relationship, e.g. my manager]
What I need: [the one ask]
Key facts: [dates, reason, what''s already done, what I''m offering]
Tone: [polite / warm / firm]

Success looks like: the reader knows what I need in the first two lines and can reply yes in one sentence.

Steps:
1. Subject line that states the ask (e.g. "Request: 2-day extension for the Q3 report")
2. First two lines: the ask and the date
3. One sentence of reason, then the plan that reduces their effort or risk
4. Close with one clear question

Rules: under 150 words; paragraphs of 1–3 sentences; no "I hope this email finds you well", over-apologising or "Please do the needful"; use [placeholders] for anything I haven''t told you.

Output: subject line (+1 alternative), the email, and a WhatsApp/chat version under 50 words.'),
('summarize-any-document', 'You are an analyst who writes accurate executive summaries for busy readers, using only the source.

Summarise for: [who will read it, and what they''ll do with it]
"""
[paste text]
"""

Success looks like: the reader can make the right decision without opening the original.

Output:
1. Summary in 3 sentences, conclusion first
2. 5–7 key points (keep numbers, names and dates exact)
3. Decisions or action items, if any
4. What''s unclear, missing or unsupported in the text

Rules: use only information in the text; quote briefly when exact wording matters; no opinions unless I ask.'),
('translate-naturally', 'Translate the text below into [target language] for [audience, e.g. customers in Mumbai].
Tone: [formal / friendly / same as original]

"""
[paste text]
"""

Translate meaning, not word by word. Keep names, numbers, links and formatting intact. After the translation, list any phrases with no direct equivalent and how you handled them.'),
('presentation-outline', 'You are a presentation coach who builds talks around one memorable message and slides with one idea each.

Topic: [topic]
Audience: [who, and what they already know]
Length: [number] slides, [minutes] minutes
The one thing they should remember: [key takeaway]
What I want them to do afterwards: [action]

Success looks like: someone who missed the talk can repeat the key takeaway after skimming the slides.

Steps:
1. Write the key takeaway as one sentence and build the story around it: hook → problem → insight → evidence → action
2. One idea per slide; slide titles are full-sentence claims, not labels ("Late deliveries cost us 12% of repeat orders", not "Deliveries")
3. For each slide, suggest a visual (chart type, photo, diagram) instead of text bullets
4. Write speaker notes I can say in the time available (about 130 words per minute)

Output: a table with slide # | headline claim | up to 3 bullets (≤8 words each) | visual | speaker notes (2–4 sentences). Then 3 likely audience questions with short answers.

Rules: no more than 3 bullets per slide; use [placeholder] for any data I haven''t given; the timing must add up to my talk length.'),
('bedtime-story-for-kids', 'Write a bedtime story for a [age]-year-old named [name] who loves [interests].
Theme or lesson: [e.g. being brave, sharing]
Length: about [word count] words.

Use simple words, a calm rhythm, a small problem that gets solved kindly, and a peaceful ending. No scary content. Offer 2 alternative titles.'),
('learn-anything-step-by-step', 'You are a patient expert teacher. I want to learn [topic].
My level: [complete beginner / some basics]
Why I''m learning: [goal]
Time: [e.g. 30 minutes a day]

1. Ask me 3 quick questions to check what I already know.
2. Break the topic into 5–7 building blocks and show me the map.
3. Teach block 1 with a simple everyday example, then give me one practice question.
4. Wait for my answer, correct it kindly, then continue.
Avoid jargon unless you define it.'),
('exam-revision-plan', 'Help me prepare for [exam name] on [date].
Syllabus/subjects: [list or "use the official syllabus"]
Strong areas: [ ]
Weak areas: [ ]
Study time: [hours per day]

Create: a priority table (topic · weight · my confidence · priority), a day-by-day revision schedule up to the exam with buffer days, a practice-test plan, and a simple mistake-log routine.
Remind me to check the official syllabus and pattern; don''t assume they''re current.'),
('flashcards-from-notes', 'You are a learning scientist who writes flashcards for active recall and spaced repetition.

Notes:
"""
[paste notes]
"""
Number of cards: [number]
Exam or goal: [e.g. biology class 12 board exam]

Success looks like: cards that test understanding, so I can tell what I actually know.

Rules:
- One idea per card; no "list everything about X" cards
- Mix types: definition, why/how, apply-to-an-example, compare two concepts
- Answers under 25 words; use only my notes
- Add a cloze card (fill-in-the-blank) for key formulas or terms

Output: one card per line as "Front | Back" so I can import it into Anki or Quizlet, then the 3 concepts from my notes most likely to be tested.'),
('explain-like-im-new', 'You are a patient teacher who explains hard ideas with everyday analogies and checks understanding before going deeper.

Explain: [concept]
My background: [e.g. no science background, class 10 maths]
Why I''m asking: [e.g. a news article, an exam, work]

Success looks like: I can explain it back to a friend in two sentences and avoid the most common misunderstanding.

Structure:
1. One-sentence plain answer
2. An everyday analogy, and where the analogy breaks down
3. A slightly deeper explanation (under 150 words)
4. A common misconception and why it''s wrong
5. One question to check I understood; wait for my answer

Rules: define every technical word the first time; no jargon without a definition; under 350 words before the check question.'),
('product-photo-prompt', 'A professional product photograph of [product, with colour/material], placed on [surface, e.g. light oak table], [setting: clean studio / cosy kitchen / outdoor café].
Lighting: soft diffused window light from the left, gentle shadow.
Camera: 45-degree angle, 50mm lens look, shallow depth of field, product in sharp focus.
Mood: [e.g. fresh, minimal, premium]. Colour palette: [colours].
Aspect ratio [1:1 / 4:5]. No text, no logos, no watermark. Keep the product''s shape and label accurate.'),
('logo-concepts-brief', 'You are a brand identity designer.
Brand: [name] — [what it does]
Audience: [who]
Personality: [3 words, e.g. calm, premium, eco]
Avoid: [styles/colours you dislike]

Propose 3 distinct concepts (one symbol, one wordmark, one combination). For each: idea and rationale, colour palette with hex codes, font style suggestions, and a prompt I can paste into an image generator to visualise it.
Don''t imitate existing trademarks.'),
('video-shot-prompt', 'Shot: [medium shot / close-up / aerial]
Subject & action: [who/what does what, e.g. a potter shapes a clay bowl on a wheel]
Camera: [slow dolly in / orbit / static]
Setting: [place and time, e.g. sunlit workshop, late afternoon]
Style: cinematic, natural colours, shallow depth of field, consistent lighting
Duration: [6–8 seconds]
Audio (if supported): [ambient sounds]
Aspect ratio: [16:9 / 9:16]'),
('thumbnail-concepts', 'Video title: [title]
What the viewer gets: [payoff]
Channel style: [colours, face/no face]

Give 3 thumbnail concepts: focal subject, facial expression (if any), 2–4 words of text, colour contrast, composition. Then an image-generator prompt for each (leave space for text; I''ll add it in an editor).
It must be readable on a phone and honest to the video.'),
('job-interview-coach', 'You are an experienced interviewer and interview coach.
Role: [job title]
Company: [company and what it does]
My background: [experience, key achievements]
Interview type: [HR / technical / case / panel]

1. List the 10 most likely questions (behavioural, role-specific, about the company).
2. For the 3 hardest, show how to structure a strong STAR answer using my real experience (use [placeholders] where you need my examples; never invent experience).
3. Run a mock interview: ask one question at a time, wait for my answer, then give specific feedback and a stronger version.
4. Suggest 3 smart questions I can ask the interviewer.'),
('resume-bullet-upgrade', 'You are a recruiter who has screened thousands of resumes for [job title] roles and knows what ATS filters and 6-second scans look for.

Target role: [job title]
Job description (key parts): [paste]
My current bullets:
[paste bullets]

Success looks like: every bullet shows action + result, matches the job''s keywords, and nothing is invented.

Steps:
1. Pull the 10 most important keywords from the job description
2. Rewrite each bullet as strong verb + what I did + result; where a number would help, write [add metric] instead of inventing one
3. Reorder bullets so the most relevant proof comes first
4. List gaps between my resume and the role, and honest ways to address them

Output: keyword table (keyword | in my resume? | where to add) · before → after bullets · gaps · 3 questions whose answers would make my weakest bullets stronger.
Rules: max 2 lines per bullet; no "responsible for"; never invent metrics, tools or titles.'),
('salary-raise-conversation', 'Help me ask my manager for a raise.
My role and time in role: [ ]
Achievements this year: [ ]
What I''m asking for: [amount or %]
Market info I have: [salary data and source, if any]

Give: 4 evidence-based talking points, a calm opening script, likely manager responses with how to reply (including "not now"), and a short follow-up email summarising the conversation.
Keep it professional; no ultimatums.'),
('plan-my-day-time-blocks', 'Plan my day.
Available hours: [e.g. 9:00–18:00]
Fixed commitments: [meetings, calls, school pickup]
Tasks: [list everything]
Energy: [when I focus best]

1. Sort tasks into must / should / could.
2. Estimate time for each (ask if unclear).
3. Build a time-blocked schedule with breaks and a 30-minute buffer.
4. Tell me what to drop, delegate or move to tomorrow.'),
('trip-itinerary-budget', 'Plan a [number]-day trip to [destination] in [month].
Travellers: [who]
Budget: [total or per day]
Interests: [food, nature, history, nightlife…]
Pace: [relaxed / packed]

Give: a day-by-day table (morning · afternoon · evening · travel time), areas to stay with reasons, local food to try, an estimated budget split, and a checklist of bookings.
Prices, opening hours and visa rules change, so mark what I should verify.'),
('weekly-meal-plan', 'Create a 7-day meal plan.
People: [number, ages]
Diet/allergies: [e.g. vegetarian, no peanuts]
Cuisine preferences: [ ]
Cooking time: [e.g. 30 minutes on weekdays]
Budget: [weekly amount]

Give: a table (day · breakfast · lunch · dinner), a grocery list grouped by section, and 3 prep-ahead tips.
If any diet is for a medical condition, remind me to follow my doctor''s or dietitian''s advice.'),
('habit-system-design', 'You are a behaviour-change coach who designs habits using tiny starting versions, existing routines as triggers, and simple tracking.

Habit I want: [habit]
Why it matters to me: [reason]
My typical day: [wake time, work hours, evenings]
What stopped me before: [obstacles]

Success looks like: a habit small enough to do on my worst day, attached to something I already do, with a plan for missed days.

Steps:
1. Define the 2-minute version I can do daily, and the full version I''m building towards
2. Pick an anchor: "After I [existing routine], I will [tiny habit]" (give 3 options from my day)
3. Remove friction for each obstacle I listed with one specific change
4. Give a copy-paste tracker (text table, 4 weeks)
5. Rules for missed days (never miss twice) and how to grow the habit every 2 weeks

Output: tiny version · 3 anchor options · obstacle → fix table · 4-week tracker · growth plan.
Rules: no motivation speeches; every suggestion is a concrete action with a time or place.'),
('spreadsheet-formula-helper', 'App: [Excel / Google Sheets]
Sheet layout: [e.g. A: date, B: product, C: quantity, D: price; data in rows 2–500]
What I need: [e.g. total sales per month in a summary table]

Give the formula, explain each part in plain words, mention edge cases (blanks, text in number columns, different date formats), and offer one alternative approach (e.g. pivot table).'),
('analyze-data-insights', 'Analyse the data below (or the attached file).
Context: [what the data is, time period]
Questions I want answered: [1–3 questions]

"""
[paste data or describe the attached file]
"""

1. Describe the dataset and check quality (missing values, duplicates, outliers).
2. Answer each question, showing how you calculated it.
3. Suggest 2–3 charts that would make the findings clear.
4. State limitations and what extra data would help.
Compute only from the data provided; don''t invent numbers.'),
('survey-results-themes', 'Here are survey responses from [who, how many people]:
"""
[paste responses]
"""

1. Summarise any rating/numeric questions.
2. Group open-ended answers into themes (table: theme · count · example quote).
3. Highlight differences between segments if the data shows them.
4. List 3 implications and the limits of this sample.
Don''t over-claim from small samples.'),
('compare-options-table', 'You are a neutral research analyst who compares options against the buyer''s own priorities and is clear about what needs verifying.

Options: [option A], [option B], [option C]
My use case: [what I''ll use it for]
What matters most (in order): [criteria, e.g. price, ease of use, privacy]
Budget: [amount]

Success looks like: I can see which option fits my priorities best, why, and what to double-check before buying.

Steps:
1. Assign weights to my criteria (summing to 100) based on my order
2. Score each option 1–5 per criterion with a one-line reason
3. Calculate weighted totals and show the maths
4. Recommend the best fit, plus one alternative for a different priority

Output: comparison table (option | each criterion score | weighted total) · recommendation · "verify before buying" list.
Rules: mark any price, spec or feature that may be outdated as [verify]; don''t invent specs.'),
('monthly-budget-builder', 'You are a personal finance educator, not a financial advisor.
Monthly take-home income: [amount]
Fixed costs: [rent, EMIs, bills]
Variable spending: [food, transport, shopping…]
Goals: [emergency fund, trip, paying off a loan]

1. Organise my numbers into a budget table.
2. Suggest a realistic split and where I could save, explaining your reasoning.
3. Give a step-by-step savings plan for my goals.
4. Add a 10-minute monthly review checklist.
Use only my numbers and label any example figures as hypothetical. This is educational, not personalised financial advice; suggest when to talk to a licensed advisor.'),
('explain-investing-basics', 'Explain [investment product, e.g. index mutual fund SIPs] to a beginner in [country].

Cover: how it works, costs and fees to look for, the main risks, how it''s taxed in general terms (tell me to verify current rules on official sources), and a simple example with clearly hypothetical numbers.
End with 5 questions I should ask a licensed financial advisor.
This is education, not a recommendation; don''t tell me what to buy and don''t promise returns.'),
('health-question-safely', 'I have a general health question: [question]
Relevant context (optional): [age range, general situation]

Please give general, evidence-based information from reliable sources (e.g. WHO, national health services) and name them. Explain common causes or options in general terms, list warning signs that need prompt medical attention, and suggest questions I can ask a doctor.
This is not a diagnosis or treatment plan. Recommend that I consult a qualified healthcare professional.'),
('legal-situation-explainer', 'Jurisdiction: [country and state/city]
My situation: [describe briefly, without sharing private identifiers]
What I want: [outcome]

Explain the general legal position in plain language, cite the relevant law or official source where possible (say if unsure), list my typical options and steps (e.g. written notice, consumer forum), and tell me when I should consult a qualified lawyer.
This is general legal information, not legal advice.'),
('science-explainer-layers', 'Explain [science or technology topic] in layers:
1. One-sentence answer a 10-year-old would get.
2. An everyday analogy.
3. The real mechanism for a high-school level.
4. One deeper detail for someone curious.
5. What scientists are still unsure about.
Keep it accurate; mention if something is a simplification.'),
('perplexity-sourced-research', 'Research question: [your question]
Time range: [e.g. last 12 months]  Region: [e.g. India]

Give:
1. A 3-sentence direct answer.
2. Evidence: bullet points, each with the source name, URL and publication date.
3. Where sources disagree, say so and explain why.
4. What is unknown or not publicly available.
Do not state numbers without a cited source.'),
('claude-document-analysis', '<document>
[paste document]
</document>

<task>
Answer the questions below using only the document. For each answer, include a short supporting quote.
</task>

<questions>
1. [question]
2. [question]
</questions>

<format>
Numbered answers. If the document doesn''t answer a question, write "Not in document".
</format>'),
('chatgpt-cold-email', '## Context
I am [who you are / your business]. I''m emailing [recipient role] at [company type] because [specific reason relevant to them].

## Task
Write a cold email offering [offer].

## Constraints
- Under 120 words
- First line about them, not me
- One clear call to action: [CTA]
- No buzzwords, no exaggerated claims

## Output format
Subject line + email body. Then give one alternative subject line.'),
('grok-x-thread', '## Task
Turn my notes below into an X thread of 5–7 posts.

## Notes
[paste notes]

## Constraints
- Post 1 states the main insight plainly (no clickbait)
- Each post under 270 characters
- Only use facts from my notes; don''t add statistics
- End with a simple question to invite replies

## Output format
Numbered posts.'),
('gemini-study-plan', '## Role
You are a learning coach who uses spaced repetition and hands-on practice, and sizes every task to my real schedule.

## Task
Create a 4-week plan to learn [skill], starting from [current level, e.g. complete beginner].
Success looks like: by week 4 I can [concrete outcome, e.g. build a monthly sales report on my own], proven by a final mini-project.

## My situation
- Time: [minutes per day] on [days per week]
- Why I''m learning: [job task / exam / project]

## Steps
1. Turn the goal into 3 things I''ll be able to do, plus a final mini-project
2. Order topics by dependency into 4 weekly milestones
3. Each day: one learn task + one practice task, within my daily time
4. Spaced review on days 1, 3 and 7 after each topic; a 5-question self-test each week
5. A weekly catch-up slot, and what to cut if I fall behind

## Output format
- Weekly milestones table: week | milestone | proof I can do it
- Daily plan table: day | learn (min) | practise (min) | review
- Weekly self-test (5 questions)
- Final mini-project brief

## Rules
- Every day includes doing, not just watching or reading
- Name resource types (official docs, practice datasets), not invented course titles or links
- If anything in [brackets] is missing, ask me before planning'),
('meeting-notes-summary', 'You are a chief of staff who turns messy meeting notes into clear decisions and owned action items.

Meeting: [name / purpose], attendees: [names]
Notes or transcript:
"""
[paste notes or transcript]
"""

Success looks like: anyone who missed the meeting knows what was decided, who does what by when, and what''s still open.

Output:
1. Summary (2 sentences, outcome first)
2. Decisions made (bullets, with who decided if stated)
3. Action items table: task | owner | deadline | status. Write "unassigned" or "no date" when missing; never guess an owner
4. Open questions and risks
5. A 5-line follow-up message I can send to attendees

Rules: use only what is in the notes; keep names, numbers and dates exactly as written; flag contradictions.'),
('midjourney-product-hero', '[product, with colour and material], on a [material, e.g. travertine] pedestal, commercial product photography, soft gradient background in [colour], large softbox key light from the left with subtle rim light, soft shadow, 45-degree angle, 100mm macro lens, product centred and in sharp focus, shallow depth of field, true-to-life colours, minimal composition --ar 4:5 --no text, watermark, warped label, extra objects, harsh reflections'),
('resume-bullets', 'Rewrite these resume bullets for a [target role] application:
"""
[paste bullets]
"""
Rules:
- Start each with a strong verb; show the result or impact
- Use numbers ONLY if they appear in my original text; otherwise write [add metric] as a placeholder
- Max 2 lines each
Return the rewritten bullets, then 3 questions whose answers would make them stronger.'),
('80s-yearbook-portrait', 'Transform the uploaded photo into a 1980s American high-school yearbook portrait. Keep the exact same face, facial features, skin tone and expression as the uploaded photo. Do not change the person''s identity.
Style: soft studio lighting, mottled blue laser-style backdrop, slightly faded warm film colors, subtle film grain, era-appropriate hairstyle and clothing (big hair, denim jacket or patterned sweater).
Framing: head-and-shoulders, centered, slight smile. Aspect ratio 4:5.
No text, no watermark.'),
('multiverse-persona-carousel', 'Using the uploaded photo, create a 2×5 grid of ten panels showing the same person as ten different personas: astronaut, chef, rock musician, 1920s detective, doctor, farmer, pop star, medieval knight, scientist, street artist.
Rules for every panel: Keep the exact same face, facial features, skin tone and expression as the uploaded photo. Do not change the person''s identity. Keep the same pose (standing, facing camera, slight smile) and the same background (city park, warm golden-hour light). Only the outfit, props and hairstyle change.
Each panel the same size with a thin white border. No text.'),
('halloween-zombie-makeup', 'Apply realistic film-quality zombie special-effects makeup to the person in the uploaded photo. Keep the exact same face, facial features, skin tone and expression as the uploaded photo. Do not change the person''s identity. The person must stay recognisable under the makeup.
Details: pale grey-green skin, subtle cracked texture, dark sunken eyes, light fake blood at the lip corner, torn clothing. Moody blue-green night lighting with fog. Horror movie poster feel, not gory. Aspect ratio 4:5.'),
('diwali-festive-portrait', 'Edit the uploaded photo into a festive Diwali portrait. Keep the exact same face, facial features, skin tone and expression as the uploaded photo. Do not change the person''s identity.
Outfit: elegant traditional Indian wear (silk kurta or saree in deep maroon and gold).
Setting: home balcony at dusk with rows of lit clay diyas, marigold garlands and soft bokeh fairy lights.
Lighting: warm candle glow on the face, natural skin texture. Aspect ratio 4:5. No text.'),
('collectible-figurine-box', 'Create a photorealistic 1/7 scale collectible figure of the person in the uploaded photo, standing on a round clear acrylic base on a wooden desk. Keep the exact same face, facial features, skin tone and expression as the uploaded photo. Do not change the person''s identity.
Next to it: the figure''s retail box with original artwork of the same character, and a computer monitor showing the 3D modelling software view of the figure.
Soft indoor daylight, shallow depth of field, product photography style. Aspect ratio 1:1.'),
('action-figure-blister-pack', 'Turn the person in the uploaded photo into a plastic action figure sealed in a toy blister pack. Keep the exact same face, facial features, skin tone and expression as the uploaded photo. Do not change the person''s identity.
Packaging: bright card backing with the name "[YOUR NAME]" at the top and a tagline "[YOUR TAGLINE]". Accessories in separate plastic slots: [accessory 1], [accessory 2], [accessory 3].
Studio product lighting, glossy plastic reflections. Aspect ratio 4:5.'),
('blockbuster-movie-poster', 'Create a cinematic movie poster starring the person in the uploaded photo. Keep the exact same face, facial features, skin tone and expression as the uploaded photo. Do not change the person''s identity.
Genre: [action / romance / thriller]. Title text: "[MOVIE TITLE]" in bold cinematic typography at the bottom, with a tagline "[TAGLINE]" and small credit-block text.
Dramatic teal-and-orange color grade, rim lighting, epic background matching the genre. Aspect ratio 2:3.'),
('1970s-polaroid', 'Recreate the uploaded photo as a 1970s Polaroid instant photo. Keep the exact same face, facial features, skin tone and expression as the uploaded photo. Do not change the person''s identity. (applies to every person in the photo)
Look: faded warm colors, slight vignette, soft focus, light chemical streaks, white Polaroid frame with a thicker bottom border. Casual candid feel. Aspect ratio 1:1 inside the frame.'),
('90s-disposable-flash', 'Restyle the uploaded photo to look like it was taken on a cheap 1990s disposable film camera with direct flash. Keep the exact same face, facial features, skin tone and expression as the uploaded photo. Do not change the person''s identity.
Look: harsh on-camera flash, dark falloff in the background, slightly overexposed skin highlights, visible grain, orange date stamp in the bottom-right corner reading "[DATE]". Aspect ratio 3:2.'),
('linkedin-headshot', 'Turn the uploaded photo into a professional headshot suitable for LinkedIn. Keep the exact same face, facial features, skin tone and expression as the uploaded photo. Do not change the person''s identity. Keep natural skin texture; no heavy retouching or face slimming.
Outfit: [navy blazer over white shirt]. Background: plain soft grey studio backdrop. Lighting: soft key light from the left with gentle fill. Framing: head and shoulders, eyes at upper third. Aspect ratio 1:1.'),
('restore-old-photo', 'Restore the uploaded old photograph. Remove scratches, dust, creases and stains; fix fading and contrast; sharpen gently.
Then colorize it with natural, period-appropriate colors. Keep the exact same face, facial features, skin tone and expression as the uploaded photo. Do not change the person''s identity. Do not add or remove people or objects, and do not change clothing or background details. Keep the original framing.'),
('golden-hour-street-portrait', 'Edit the uploaded photo into a cinematic golden-hour street portrait. Keep the exact same face, facial features, skin tone and expression as the uploaded photo. Do not change the person''s identity.
Setting: a quiet old-city street with warm sunlight low behind the subject, creating soft rim light on the hair. Background softly blurred (shallow depth of field, 85mm lens look). Subtle Kodak Portra-style film tones and fine grain. Aspect ratio 4:5.'),
('cinematic-couple-still', 'Turn the uploaded couple photo into a still frame from a romantic film. Keep both people''s exact faces, features, skin tones and expressions unchanged.
Scene: [rainy city street at night with neon reflections / beach at sunset]. Anamorphic widescreen look with subtle lens flare, soft film grain, letterbox bars. Aspect ratio 16:9 (2.39:1 inside the letterbox).'),
('reel-cover-bold-text', 'A vertical 9:16 Reel cover image: [subject, e.g. a steaming cup of masala chai on a wooden table], bold minimal composition with large empty space in the top third for a title. Vibrant but natural colors, soft side light, high contrast subject against a clean background. If the model supports text, add the title "[TITLE]" in thick sans-serif at the top; otherwise leave the space empty.'),
('product-flatlay', 'Overhead flat-lay product photo of [your product] on a [linen / terrazzo / pastel paper] surface, surrounded by a few related props ([prop 1], [prop 2]) with plenty of negative space. Soft diffused daylight from a window, gentle shadows, true-to-life colors. Aspect ratio 4:5. No text, no logos other than the product''s own.'),
('slow-motion-food-reel', 'Shot: extreme close-up
Subject & action: [hot ghee being poured over a stack of fresh parathas], steam rising, slow motion
Camera: slow dolly in
Setting: rustic kitchen counter, warm morning window light
Style: cinematic food commercial, shallow depth of field, rich warm colors
Duration: 8 seconds
Audio: soft sizzle and gentle ambient kitchen sounds
Aspect ratio: 9:16'),
('travel-reel-drone-reveal', 'Shot: aerial shot
Subject & action: a lone traveller standing on a cliff edge, the camera rises to reveal [a misty Himalayan valley at sunrise]
Camera: crane up and slow push forward
Style: cinematic, natural colors, soft volumetric light through mist
Duration: 8 seconds
Audio: wind and distant birds, no music
Aspect ratio: 9:16'),
('hi-saree-portrait', 'अपलोड की गई फोटो को एक सुंदर साड़ी पोर्ट्रेट में बदलें। चेहरा, चेहरे की बनावट, त्वचा का रंग और भाव बिल्कुल वैसे ही रखें — व्यक्ति की पहचान न बदलें।
साड़ी: [रंग, जैसे गहरा लाल सिल्क, सुनहरी ज़री बॉर्डर]।
पृष्ठभूमि: पुरानी हवेली का आंगन, हल्की धूप।
रोशनी: शाम की सुनहरी रोशनी, प्राकृतिक त्वचा। आस्पेक्ट रेशियो 4:5। कोई टेक्स्ट या वॉटरमार्क नहीं।'),
('hi-old-photo-restore', 'इस पुरानी फोटो को रिस्टोर करें: खरोंच, धूल, मोड़ और दाग हटाएं; फीके रंग और कॉन्ट्रास्ट ठीक करें; हल्का शार्प करें।
फिर प्राकृतिक, उस समय के अनुसार रंग भरें। सभी लोगों के चेहरे और पहचान बिल्कुल न बदलें। कोई व्यक्ति या चीज़ न जोड़ें, न हटाएं। फ्रेमिंग वैसी ही रखें।'),
('hi-festive-family-portrait', 'अपलोड की गई फैमिली फोटो को त्योहार वाले पोर्ट्रेट में बदलें। हर व्यक्ति का चेहरा और पहचान बिल्कुल वैसी ही रखें।
सभी ने पारंपरिक कपड़े पहने हों। पृष्ठभूमि: रंगोली, जलते दीये, गेंदे की मालाएं और हल्की फेयरी लाइट्स।
रोशनी: गर्म, दीयों जैसी रोशनी। आस्पेक्ट रेशियो 4:5। कोई टेक्स्ट नहीं।'),
('bug-fix-with-root-cause', 'Bug: [describe what happens vs what should happen]
Steps to reproduce: [steps]
Error / logs:
"""
[paste error or stack trace]
"""

Before changing any code:
1. List the 2–3 most likely root causes, with the evidence for each.
2. Tell me which files you need to read to confirm, then read them.
3. State the confirmed root cause in one sentence.

Then fix it with the smallest change that addresses the root cause, add a regression test that fails before the fix and passes after, and run the test suite. Do not refactor unrelated code.'),
('safe-refactor', 'Refactor [file/class/function] to [goal: e.g. extract the pricing logic into a service].

Rules:
- Behaviour must not change. If tests for this code are missing, write characterisation tests first and run them.
- Keep public method signatures unless I approve changes.
- Work in small steps; run tests after each step.
- Touch only the files needed. List them before you start.

Finish with: files changed, why the new structure is better, and the test command output.'),
('write-tests-for-existing-code', 'Write tests for [file/function/endpoint] using [Pest / PHPUnit / Vitest / Jest].

Cover:
- The main happy path
- Edge cases: empty input, boundaries, invalid types, large input
- Failure paths: exceptions, validation errors, external service failure (mock it)

Test behaviour through the public interface, not private methods. Use the project''s existing factories/fixtures. Run the tests and show the output. If you find a real bug, stop and report it instead of writing a test that encodes the bug.'),
('pr-review', 'Review this diff:
"""
[paste diff or say: review the current git diff]
"""

Report findings in this order, skipping empty categories:
1. Bugs / incorrect logic
2. Security (input validation, authz, secrets, injection)
3. Performance problems (N+1 queries, unbounded loops, missing indexes)
4. Missing tests
5. Readability (only if significant)

For each: file:line, the problem, why it matters, a concrete fix. End with an overall verdict: approve / approve with changes / request changes.'),
('explain-codebase', 'I''m new to this codebase. Without changing anything, produce:
1. A one-paragraph summary of what the app does.
2. The main folders and what lives in each.
3. The request lifecycle for one typical feature (entry point → data → response), naming real files.
4. How to run it locally and run the tests (from the actual config files).
5. Anything risky or surprising you noticed (dead code, missing tests, unusual patterns).

Cite file paths for every claim. Say "not found" rather than guessing.'),
('security-audit', 'Audit [feature / files] for security issues. Check specifically:
- Authentication and authorisation on every route/action
- Input validation and output escaping (XSS)
- SQL / command / path injection
- Mass assignment and insecure direct object references
- Secrets in code, logs or client bundles
- File upload handling and SSRF (if applicable)
- Rate limiting on sensitive endpoints

Only report issues you can point to in the code (file:line), with severity (high/medium/low) and a fix. Do not change code yet.'),
('laravel-migration-safe', 'Add a migration to [describe change, e.g. add a nullable "gst_number" to customers].

Requirements:
- Create a NEW migration with php artisan make:migration; never edit existing migrations.
- Provide a working down() method.
- Add indexes for foreign keys and columns used in where/order clauses.
- For large tables, avoid changes that lock the table for long; tell me if that''s a risk.
- Update the model ($fillable, casts, relationships) and the factory.
- Add or update a feature test that uses the new column.
Run php artisan migrate and php artisan test, and show the output.'),
('laravel-n-plus-one', 'Find N+1 query problems in [controller / page / API resource].

1. Trace which relationships are accessed inside loops (controllers, Blade views, API Resources, Livewire components).
2. Fix with eager loading (with(), load(), withCount()) only where needed.
3. If useful, suggest enabling Model::preventLazyLoading() in non-production environments.
4. Show the before/after query count from a feature test using DB::enableQueryLog() or similar.
Don''t change response shape or behaviour.'),
('laravel-form-request', 'Move the validation in [Controller@method] into a dedicated Form Request.
- Generate it with php artisan make:request.
- Implement authorize() using the existing Policy/Gate (do not just return true unless there is truly no auth requirement; tell me if so).
- Keep the exact same rules and messages.
- Use $request->validated() in the controller.
- Add feature tests for one valid and two invalid payloads.'),
('laravel-queue-job', 'Move [slow work, e.g. sending invoice PDF email] from the request cycle into a queued job.
- Make the job idempotent (safe to run twice).
- Set sensible $tries, backoff and timeout; handle failure in failed().
- Pass IDs, not whole models with large relations, unless using SerializesModels intentionally.
- Use Queue::fake() / Bus::fake() in tests to assert dispatch, and a separate test for the job''s handle().
Explain how to run the worker locally.'),
('livewire-component', 'Create a Livewire component for [feature, e.g. editable invoice line items].
- Validate all input with rules; never trust public properties.
- Authorise actions (Policies) inside action methods.
- Use wire:model.live only where instant feedback is needed.
- Keep heavy queries in computed properties.
- Add a Livewire test covering render, a successful action, and a validation failure.'),
('node-endpoint-zod', 'Add [METHOD /path] to the [Express/Fastify/NestJS/Hono] API that [does X].
- Validate body/query/params with a schema (zod or the framework''s validator).
- Keep the handler thin; put logic in a service function.
- Return consistent JSON errors: { error: { code, message } } with correct status codes.
- Check authentication/authorisation.
- Write tests for success, validation failure, and unauthorised access.
Run the tests and the type checker.'),
('node-error-handling', 'Introduce centralised error handling in this [framework] app.
- Define a small set of typed application errors (NotFound, Validation, Unauthorized, Conflict).
- Add one error-handling middleware/hook that maps them to HTTP responses and logs unexpected errors without leaking stack traces to clients.
- Ensure async handlers'' rejections reach the handler.
- Update 2–3 existing routes as examples and add tests for each error type.'),
('nextjs-server-component-data', 'Refactor [page/component] to load its data in a Server Component instead of useEffect.
- Check the installed Next.js version''s docs (node_modules/next/dist/docs) for current caching and params APIs before writing code.
- Keep interactive parts in small ''use client'' components that receive data as props.
- Add loading and error states (loading.tsx / error.tsx or Suspense).
- Don''t expose secrets to the client.
Run the build to confirm there are no type or prerender errors.'),
('nextjs-route-handler', 'Create a [route handler / server action] that [mutation].
- Validate input with zod; return 400 with field errors on failure.
- Verify the user session on the server and check they own the resource.
- Return typed JSON (route handler) or a typed result object (server action).
- Revalidate affected paths/tags after mutation, using the APIs documented for this Next.js version.
- Add a test for success, validation error and unauthorised.'),
('supabase-rls-policy', 'Write Row Level Security for the [table] table.
Access rules: [e.g. users read/write their own rows; anyone reads rows where visibility = ''public''].
- Enable RLS and write one policy per operation (select/insert/update/delete) using auth.uid().
- Use column-level grants if some columns must not be user-editable.
- Write SQL tests that switch role (anon / authenticated with different user ids) and prove each rule, including a negative case per rule.
- Never use the service-role key in client code.'),
('write-agents-md', 'Read this repository''s config files (package.json/composer.json, lockfiles, CI config, test config, linters) and draft an AGENTS.md with:
- Stack and versions (from files, not guesses)
- Exact setup, dev, test, lint and build commands
- Folder structure summary
- Code-style rules evidenced by linters/config
- Testing expectations
- A "Never" list (destructive commands, secrets, editing generated files)
Mark anything you''re unsure of with TODO. Keep it under 150 lines.'),
('plan-before-code', 'Feature: [describe]
Acceptance criteria:
- [criterion 1]
- [criterion 2]

Do not write code yet. Produce:
1. Questions about anything ambiguous (max 5).
2. Files to create/modify, with one line on each change.
3. Data model / migration changes.
4. Test plan.
5. Risks and how you''ll mitigate them.
Wait for my approval before implementing.'),
('commit-message', 'Write a commit message for the staged changes (git diff --staged).
- Format: Conventional Commits (type(scope): summary), summary under 72 characters, imperative mood.
- Body: what changed and why, wrapped at 72 characters.
- Mention breaking changes with BREAKING CHANGE: if any.
Only describe changes that are actually in the diff.'),
('dependency-upgrade', 'Upgrade [package] from [current] to [target].
1. Read its changelog / upgrade guide and list breaking changes that affect this codebase (search for usages).
2. Upgrade and fix each affected usage.
3. Run the full test suite, type checker and build.
4. Do not disable lint rules, type checks or tests to make things pass.
Summarise what changed and anything that needs manual QA.'),
('performance-profile', '[Page/endpoint] is slow (~[time]). Investigate:
1. Measure: list how you will measure (query log, profiler, timing logs) and do it.
2. Identify the top bottleneck with evidence (queries, payload size, external calls, rendering).
3. Propose up to 3 fixes ranked by impact/effort.
4. Implement the top fix and show before/after measurements.
No speculative changes without measurements.'),
('sql-query-review', 'Optimise this query for [MySQL/PostgreSQL]:
"""
[paste query]
"""
Table sizes (approx): [rows]
Existing indexes: [paste or say unknown]

1. Explain what the query does.
2. Ask me for EXPLAIN / EXPLAIN ANALYZE output if you need it rather than guessing.
3. Suggest index or query changes with the reasoning and trade-offs (write cost, storage).
4. Provide the migration for any index.')
) as v(slug, body) join public.library_items li on li.slug = v.slug
on conflict (item_id) do update set body = excluded.body;

